import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.DrWxItG4.js";const g=JSON.parse('{"title":"Text commands from the server","description":"","frontmatter":{},"headers":[],"relativePath":"guide/server-text.md","filePath":"guide/server-text.md"}'),o={name:"guide/server-text.md"};function d(n,e,r,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="text-commands-from-the-server" tabindex="-1">Text commands from the server <a class="header-anchor" href="#text-commands-from-the-server" aria-label="Permalink to &quot;Text commands from the server&quot;">​</a></h1><p>A server can send <a href="/gtps-guide/messages/3-game-message">GAME_MESSAGE (3)</a> text to the client, not only receive it. This page lists every <code>action|</code> the 5.60 client reacts to, in the order its handler (<code>0x1372d28</code>) checks them.</p><ul><li>The text is <code>key|value</code> lines. The first key must be <code>action</code>, or the client logs &quot;bad net game message&quot; and ignores it.</li><li>The client overwrites the last byte of every text message with a NUL, so end the message with an extra <code>\\0</code> (gurotopia&#39;s <code>send_text()</code> does).</li><li>If the text contains <code>OnPersistentNPCMessageInputDependent</code> anywhere, the client logs &quot;Found tutorial packet&quot;. That changes nothing else.</li><li>Values are read with the client&#39;s text scanner: <code>key|value</code>, one per line. A missing key reads as an empty string, or 0 for numbers.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[u32 3] action|play_sfx\\nfile|audio/gong.wav\\ndelayMS|0\\n [\\0]</span></span></code></pre></div><h2 id="log" tabindex="-1">log <a class="header-anchor" href="#log" aria-label="Permalink to &quot;log&quot;">​</a></h2><p>Prints a line in the console, like <a href="/gtps-guide/functions/OnConsoleMessage">OnConsoleMessage</a>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Meaning</th></tr></thead><tbody><tr><td><code>msg</code></td><td>the text, with <code>\`x</code> color codes. Emoticon codes are replaced with the emoticons from <a href="/gtps-guide/functions/OnEmoticonDataChanged">OnEmoticonDataChanged</a></td></tr></tbody></table><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (action </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;log&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    std::string text </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ReplaceEmoticons</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(g_emoticons, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;msg|&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 0x1e63e84</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    AddToLog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(text);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                                     // 0x1716724: the console log</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="logoff" tabindex="-1">logoff <a class="header-anchor" href="#logoff" aria-label="Permalink to &quot;logoff&quot;">​</a></h2><p>No other keys. The client disconnects its ENet peer (<code>enet_peer_disconnect(peer, 0)</code>), and its normal disconnect handling follows.</p><h2 id="play-sfx" tabindex="-1">play_sfx <a class="header-anchor" href="#play-sfx" aria-label="Permalink to &quot;play_sfx&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Meaning</th></tr></thead><tbody><tr><td><code>file</code></td><td>the sound file, e.g. <code>audio/gong.wav</code></td></tr><tr><td><code>delayMS</code></td><td>wait this many ms before playing it</td></tr></tbody></table><p>The sound is played through the audio queue (<code>0x1e433d4</code>, channel type 15).</p><h2 id="play-music" tabindex="-1">play_music <a class="header-anchor" href="#play-music" aria-label="Permalink to &quot;play_music&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Meaning</th></tr></thead><tbody><tr><td><code>file</code></td><td>the music file, or <code>stop</code></td></tr><tr><td><code>delayMS</code></td><td>wait this many ms before starting it</td></tr></tbody></table><p><code>file|stop</code> stops the current music immediately and clears the GUI root&#39;s music flag (+0x2f0). Any other value is queued like <code>play_sfx</code>, with type 20 (music).</p><h2 id="add-notification" tabindex="-1">add_notification <a class="header-anchor" href="#add-notification" aria-label="Permalink to &quot;add_notification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Meaning</th></tr></thead><tbody><tr><td><code>imageFile</code></td><td>the picture, e.g. <code>interface/atomic_button.rttex</code></td></tr><tr><td><code>msg</code></td><td>the text</td></tr><tr><td><code>audioFile</code></td><td>a sound to play with it (can be empty)</td></tr><tr><td><code>delayMS</code></td><td>wait this many ms first</td></tr></tbody></table><p>After <code>delayMS</code> the client runs <a href="/gtps-guide/functions/OnAddNotification">OnAddNotification</a><code>(imageFile, msg, audioFile)</code> on the GUI root. After <code>delayMS + 1000</code> it also runs <code>OnAddLog(msg)</code> there, which adds the text to the log.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RunLater</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GetApp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">gui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, delayMS,        </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OnAddNotification&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { image, msg, audio });</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 0x1e443fc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RunLater</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GetApp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">gui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, delayMS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OnAddLog&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,          { msg });</span></span></code></pre></div><h2 id="logon-fail" tabindex="-1">logon_fail <a class="header-anchor" href="#logon-fail" aria-label="Permalink to &quot;logon_fail&quot;">​</a></h2><p>No other keys. The login was refused.</p><ul><li><strong>First connection</strong> (logon mode 0, netclient+0xc0): the client sends <code>action|quit</code> and disconnects (<code>0x11424bc</code>).</li><li><strong>After a redirect</strong> (logon mode not 0): it disconnects and reconnects after 2 seconds (<code>0x11433d4</code>).</li></ul><p>See <a href="/gtps-guide/guide/official-login#_3-enet-the-login-server">Login on the official servers</a>.</p><h2 id="everything-else-gametextmessage" tabindex="-1">Everything else: GameTextMessage <a class="header-anchor" href="#everything-else-gametextmessage" aria-label="Permalink to &quot;Everything else: GameTextMessage&quot;">​</a></h2><p>Any other action is passed on as GameLogic&#39;s <code>GameTextMessage</code> function with <code>{ action name, the whole text }</code>. Only two screens listen to it, so these are the only other actions the client handles.</p><h3 id="the-connection-screen-set-url-request-token-request-captcha" tabindex="-1">The connection screen: set_url, request_token, request_captcha <a class="header-anchor" href="#the-connection-screen-set-url-request-token-request-captcha" aria-label="Permalink to &quot;The connection screen: set_url, request_token, request_captcha&quot;">​</a></h3><p>These are only handled while the connection screen is up (during login). They&#39;re described on <a href="/gtps-guide/guide/official-login#_5-game-messages-during-login">Login on the official servers</a>.</p><p><small>Listener: <code>0x1b6d8c4</code> → <code>0x1b79f08</code> → <code>0x1b737ac</code>.</small></p><h3 id="the-world-menu-world-validated" tabindex="-1">The world menu: world_validated <a class="header-anchor" href="#the-world-menu-world-validated" aria-label="Permalink to &quot;The world menu: world_validated&quot;">​</a></h3><p>The answer to <a href="/gtps-guide/actions/validate_world">action|validate_world</a>, which the client sends while you type a world name in the world menu.</p><table tabindex="0"><thead><tr><th>Key</th><th>Meaning</th></tr></thead><tbody><tr><td><code>available</code></td><td><code>1</code>: the world doesn&#39;t exist yet. <code>-1</code>: the name isn&#39;t valid. Anything else: the world exists</td></tr><tr><td><code>world_name</code></td><td>the name it&#39;s about</td></tr></tbody></table><p>The client stores the name and the time, then sets the hint text under the name box and the button (<code>0x1c13544</code>):</p><table tabindex="0"><thead><tr><th>Case</th><th>Hint text</th><th>Button</th></tr></thead><tbody><tr><td>empty name</td><td>&quot;Enter a unique name to create a new world!&quot;</td><td></td></tr><tr><td><code>start</code></td><td>&quot;Enter a world name to join friends or create your own!&quot;</td><td></td></tr><tr><td><code>available|1</code></td><td>&quot;Hit Enter or click &#39;Create World&#39; to make this world!&quot; (on other platforms &quot;Press &#39;Y&#39;…&quot;, &quot;Press &#39;X&#39;…&quot; or &quot;Tap &#39;Create World&#39;…&quot;)</td><td>Create World</td></tr><tr><td><code>available|-1</code></td><td>&quot;Invalid world name - please try again!&quot;</td><td></td></tr><tr><td>other, while creating a world (probably, <code>0x1c15d04</code>)</td><td>&quot;This world already exists. Try another name!&quot;</td><td></td></tr><tr><td>other</td><td>&quot;Hit Enter or click &#39;Create World&#39; to enter this world!&quot; (or the Y / X / Tap versions)</td><td>Enter World</td></tr></tbody></table><p>Afterwards the client compares <code>world_name</code> with the name it is waiting for (+0x3e0); probably so an old answer doesn&#39;t change the button for a newer name.</p><p><small>Listener: <code>0x1c10eb8</code> → <code>0x1c17f14</code> → <code>0x1c174e0</code>.</small></p><h2 id="where-this-comes-from" tabindex="-1">Where this comes from <a class="header-anchor" href="#where-this-comes-from" aria-label="Permalink to &quot;Where this comes from&quot;">​</a></h2><p><small>Handler: <code>0x1372d28</code> (case 3 of the message dispatcher <code>0x114276c</code>); text scanner <code>0x157f12c</code>, <code>0x157f82c</code>.</small></p>`,38)])])}const u=t(o,[["render",d]]);export{g as __pageData,u as default};
